function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  if (root.some(v => v !== null && !Number.isInteger(v))) return 'Node values are whole numbers.';
  const count = root.filter(v => v !== null).length;
  if (count > 1000) return 'The tree has at most 1000 nodes.';
  // Walk the level order: each node's two children are the next two entries.
  let next = 1;
  let seen = 0;
  const queue = [root[0]];
  for (let q = 0; q < queue.length; q++) {
    const val = queue[q];
    seen++;
    const left = next < root.length ? root[next] : null;
    const right = next + 1 < root.length ? root[next + 1] : null;
    next += 2;
    if ((left === null) !== (right === null)) return 'Every node has either 0 or 2 children.';
    if (left === null && val !== 0 && val !== 1) return 'Leaves hold 0 or 1.';
    if (left !== null && val !== 2 && val !== 3) return 'Internal nodes hold 2 or 3.';
    if (left !== null) queue.push(left, right);
  }
  if (seen !== count) return 'Every value must belong to a node of the tree.';
  return null;
}

