function evaluateTree(root) {
  // List the nodes breadth-first, then settle them from the last to the first,
  // so both children of a node always have a result before the node itself.
  const order = [root];
  for (let i = 0; i < order.length; i++) {
    if (order[i].left) order.push(order[i].left, order[i].right);
  }
  const result = new Map();
  for (let i = order.length - 1; i >= 0; i--) {
    const node = order[i];
    if (!node.left) result.set(node, node.val === 1);
    else if (node.val === 2) result.set(node, result.get(node.left) || result.get(node.right));
    else result.set(node, result.get(node.left) && result.get(node.right));
  }
  return result.get(root);
}

