function generate(rand, size) {
  // A full binary tree always has an odd number of nodes.
  const target = size === 'large' ? 801 + 2 * Math.floor(rand() * 100) : 1 + 2 * Math.floor(rand() * 7);
  const nodes = [{ val: 0, left: null, right: null }];
  const leaves = [0];
  // Deep trees keep splitting one of the newest leaves, which builds long chains.
  const deep = rand() < 0.35;
  while (nodes.length < target) {
    const k = deep ? Math.max(0, leaves.length - 1 - (rand() < 0.5 ? 0 : 1)) : Math.floor(rand() * leaves.length);
    const leaf = leaves[k];
    leaves.splice(k, 1);
    nodes[leaf].left = nodes.length;
    nodes.push({ val: 0, left: null, right: null });
    nodes[leaf].right = nodes.length;
    nodes.push({ val: 0, left: null, right: null });
    leaves.push(nodes[leaf].left, nodes[leaf].right);
  }
  for (const node of nodes) node.val = node.left === null ? (rand() < 0.5 ? 0 : 1) : (rand() < 0.5 ? 2 : 3);
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
